(()=>{const input=document.querySelector('#rider-search-input'),list=document.querySelector('#rider-search-results');if(!input||!list)return;let timer,controller;const close=()=>{list.innerHTML='';list.hidden=true};const render=rows=>{if(!rows.length){list.innerHTML='<p>No rider found yet.</p>';list.hidden=false;return}list.innerHTML=rows.map(r=>'<a href="/rider/?id='+encodeURIComponent(r.id)+'">'+String(r.name).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))+'</a>').join('');list.hidden=false};input.addEventListener('input',()=>{clearTimeout(timer);const q=input.value.trim();if(q.length<2){close();return}timer=setTimeout(async()=>{if(controller)controller.abort();controller=new AbortController;try{const response=await fetch('/api/public/riders/search?name='+encodeURIComponent(q),{signal:controller.signal,cache:'no-store'});if(!response.ok)throw Error();render(await response.json())}catch(error){if(error.name!=='AbortError')close()}},180)});input.addEventListener('keydown',e=>{if(e.key==='Escape')close()});document.addEventListener('click',e=>{if(!e.target.closest('.rider-search'))close()})})();
